UPDATE budget_consumption_reversal_operation SET state_json=#{stateJson},version=#{version},status=#{status},attempts=#{attempts},updated_at=#{updatedAt},next_attempt_at=#{nextAttemptAt},lease_until=#{leaseUntil}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND input_json=#{inputJson} AND command_digest=#{digest} AND created_at=#{createdAt}
AND EXISTS (SELECT 1 FROM expense_resource_adjustment a WHERE a.tenant_id=#{expectedTenantId} AND a.id=#{adjustmentId} AND a.status<>'RETIRED')
